input=$(cat)
cmd=$(printf '%s' "$input" | jq -r '.tool_input.command // ""')

if [[ "$cmd" == *"DROP TABLE"* || "$cmd" == *"TRUNCATE"* || "$cmd" == *"DELETE FROM"* ]]; then
  cat <<JSON
{
  "hookSpecificOutput": {
    "hookEventName": "PreToolUse",
    "permissionDecision": "ask",
    "permissionDecisionReason": "This command modifies or removes table data. Review it before it runs."
  }
}
JSON
  exit 0
fi

exit 0
{"hooks": {"PreToolUse": [{"matcher": "Write|Edit|MultiEdit", "hooks": [{"type": "command", "command": "${CLAUDE_PROJECT_DIR}/.claude/hooks/protect-paths.sh", "timeout": 5}]}]}}
{
  "name": "orders-api",
  "version": "1.0.0",
  "private": true,
  "type": "module",
  "description": "Deliberately small order-management API used as the worked project throughout Graph Engineering with AI Agents.",
  "engines": {
    "node": ">=20"
  },
  "scripts": {
    "test": "node --test",
    "test:module": "node --test",
    "lint": "node scripts/lint.js",
    "format": "node scripts/lint.js --fix"
  }
}

